// Copy bench/results/*.json into web/data/bench so the site is built from the committed
// benchmark output (one source of truth, regenerated by `python bench/run_bench.py`).
import { copyFileSync, existsSync, mkdirSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, "..", "..", "bench", "results");
const dest = join(here, "..", "data", "bench");
mkdirSync(dest, { recursive: true });
if (!existsSync(src)) {
  console.warn("bench/results not found; keeping existing web/data/bench");
} else {
  for (const f of readdirSync(src).filter((f) => f.endsWith(".json"))) {
    copyFileSync(join(src, f), join(dest, f));
    console.log(`synced ${f}`);
  }
}
